-- GENERATED by tools/gen_apply_trims.js from bank/trims.json — do not edit the table by hand.
-- Idempotent, self-reporting, and it NEVER saves: his CTRL+S.
--
-- The target (RUNNING_LOG §83): a 9-voice tutti at -20 LUFS-S, so each voice at
-- -29.54 LUFS = -31.84 dB on the instrument card's scale. Every instrument in this table
-- comes DOWN: the rack was 7–21 dB hot because 0d balanced it relatively, through a REC bus trimmed
-- 12 dB down, with nothing saying how loud the ensemble should BE (§76).
--
-- Each row: the Reaper FADER carries up to +12 dB (its ceiling); any remainder goes into a stock
-- "JS: Volume Adjustment" (utility/volume) FX on the track — Reaper-side, no MIDI binding, so no CC7 can
-- ever overwrite it (ARO's own gain is bound to CC7 and tops out at unity — §58; #5's SI2 parts had the same
-- trap). A track with no remainder gets no FX; an existing one is set to 0 rather than removed.
-- The SI2 `b` instances carry their instrument's trim too — the same instrument, its curve copies — and so
-- do **Horn SI2 high** and **Horn SI2 b high**, the ReaPitch path of 1a.1, which 0d's hand-typed table
-- predated and which have therefore never been trimmed at all.
--   node tools/reaper_job.js run reaper/bridge/jobs/apply_trims.lua
local JS_NAME = 'utility/volume'
local TRIMS = {
  { name = "Flute SI2", faderDb = -23.12, extraDb = 0.00 },   -- Flute: was 0.00, -23.12
  { name = "Fluteb SI2", faderDb = -23.12, extraDb = 0.00 },   -- Flute: was 0.00, -23.12
  { name = "Clarinet SI2", faderDb = -15.94, extraDb = 0.00 },   -- Clarinet: was 0.00, -15.94
  { name = "Alto Sax SI2", faderDb = -18.27, extraDb = 0.00 },   -- Alto Sax: was 0.00, -18.27
  { name = "Alto Sax SI2 b", faderDb = -18.27, extraDb = 0.00 },   -- Alto Sax: was 0.00, -18.27
  { name = "Violin XS", faderDb = -3.30, extraDb = 0.00 },   -- Violin: was 0.00, -3.30
  { name = "Piano Kontakt", faderDb = 0.25, extraDb = 0.00 },   -- Piano: was 0.00, +0.25
  { name = "Wood Blocks ARO", faderDb = 4.26, extraDb = 0.00 },   -- Wood Blocks: was 7.05, -2.79
  { name = "Bass Drum Alt ARO", faderDb = -5.75, extraDb = 0.00 },   -- Bass Drum (Alt): was -4.29, -1.46
  { name = "Cello XS", faderDb = -3.76, extraDb = 0.00 },   -- Cello: was 8.13, -11.89
}
local function findTrack(name)
  for i = 0, reaper.CountTracks(0) - 1 do
    local tr = reaper.GetTrack(0, i); local _, n = reaper.GetTrackName(tr)
    if n == name then return tr end
  end
end
local function findFx(tr)
  for i = 0, reaper.TrackFX_GetCount(tr) - 1 do
    local _, nm = reaper.TrackFX_GetFXName(tr, i, '')
    if nm:lower():find('volume adjustment', 1, true) or nm:lower():find('utility/volume', 1, true) then return i end
  end
end
local done, missing = {}, {}
for _, r in ipairs(TRIMS) do
  local tr = findTrack(r.name)
  if not tr then missing[#missing + 1] = r.name
  else
    reaper.SetMediaTrackInfo_Value(tr, 'D_VOL', 10 ^ (r.faderDb / 20))
    local fx = findFx(tr)
    local fxDb, fxParam = nil, nil
